//! Port of `RepoOutputFormatter` (text mode): prints repo definitions for `mod show_repo`.

use crate::model::RepoSpec;

/// What a canonical repo resolves to (`RepoDefinitionValue`).
#[derive(Debug, Clone, PartialEq)]
pub enum RepoDefinition {
    /// A regular repo definition.
    Found {
        /// Canonical repo name.
        name: String,
        /// The name the extension used for the repo, if it was generated by an extension.
        original_name: Option<String>,
        spec: RepoSpec,
    },
    /// A builtin or overridden repo (`--override_repository`, `@bazel_tools`).
    RepoOverride { path: String },
}

/// `Label.getUnambiguousCanonicalForm()` of a repo-rule bzl file label.
fn unambiguous_label(label: &str) -> String {
    if label.starts_with("@@") {
        label.to_string()
    } else if let Some(rest) = label.strip_prefix('@') {
        format!("@@{rest}")
    } else if label.starts_with("//") {
        format!("@@{label}")
    } else {
        label.to_string()
    }
}

/// Prints one repo entry in the same text format as Bazel.
pub fn print_starlark(key: &str, def: &RepoDefinition, _external_directory: &str) -> String {
    let mut out = String::new();
    match def {
        RepoDefinition::Found { name, original_name, spec } => {
            out.push_str(&format!("## {key}:\n"));
            out.push_str(&format!("load(\"{}\", \"{}\")\n", unambiguous_label(&spec.bzl_file), spec.rule_name));
            out.push_str(&format!("{}(\n", spec.rule_name));
            out.push_str(&format!("  name = \"{name}\",\n"));
            if let Some(o) = original_name {
                out.push_str(&format!("  _original_name = \"{o}\",\n"));
            }
            for (k, v) in &spec.attrs {
                if k == "name" || matches!(v, crate::model::AttrVal::None) {
                    continue;
                }
                out.push_str(&format!("  {} = {},\n", k, v.repr()));
            }
            out.push_str(")\n");
            out.push('\n');
        }
        RepoDefinition::RepoOverride { path } => {
            out.push_str(&format!("## {key}:\nBuiltin or overridden repo located at: {path}\n\n"));
        }
    }
    out
}

/// Serializes a repo definition into a `build.Repository` protobuf message.
pub fn serialize_repo_definition_as_proto(
    key: &str,
    def: &RepoDefinition,
    external_directory: &str,
) -> Option<zel_proto::dynamic::Msg> {
    match def {
        RepoDefinition::Found { name, original_name, spec } => {
            let mut pb = zel_proto::dynamic::Msg::new("blaze_query.Repository");
            pb.set_str("canonical_name", name);
            pb.set_str("repo_rule_name", &spec.rule_name);
            pb.set_str("repo_rule_bzl_label", &unambiguous_label(&spec.bzl_file));

            if key.starts_with('@') {
                if !key.starts_with("@@") {
                    pb.set_str("apparent_name", key);
                }
            } else {
                pb.set_str("module_key", key);
            }
            if let Some(o) = original_name {
                pb.set_str("original_name", o);
            }

            for (k, v) in &spec.attrs {
                let mut attr_pb = zel_proto::dynamic::Msg::new("blaze_query.Attribute");
                attr_pb.set_str("name", k);
                attr_pb.set_bool("explicitly_specified", true);
                attr_pb.set_bool("nodep", false);
                match v {
                    crate::model::AttrVal::None => continue,
                    crate::model::AttrVal::Float(f) => {
                        attr_pb.set_enum("type", "DOUBLE");
                        attr_pb.set_double("double_value", *f);
                    }
                    crate::model::AttrVal::Str(s) | crate::model::AttrVal::Label(s) => {
                        attr_pb.set_enum("type", "STRING");
                        attr_pb.set_str("string_value", s);
                    }
                    crate::model::AttrVal::Int(i) => {
                        attr_pb.set_enum("type", "INTEGER");
                        attr_pb.set_int("int_value", *i);
                    }
                    crate::model::AttrVal::Bool(b) => {
                        attr_pb.set_enum("type", "BOOLEAN");
                        attr_pb.set_bool("boolean_value", *b);
                    }
                    crate::model::AttrVal::List(l) => {
                        attr_pb.set_enum("type", "STRING_LIST");
                        for item in l {
                            attr_pb.set_str("string_list_value", item.as_str().unwrap_or(""));
                        }
                    }
                    crate::model::AttrVal::Dict(d) => {
                        attr_pb.set_enum("type", "STRING_DICT");
                        for (dk, dv) in d {
                            let mut entry = zel_proto::dynamic::Msg::new("blaze_query.StringDictEntry");
                            entry.set_str("key", dk);
                            entry.set_str("value", dv.as_str().unwrap_or(""));
                            attr_pb.set_msg("string_dict_value", entry);
                        }
                    }
                }
                pb.set_msg("attribute", attr_pb);
            }

            Some(pb)
        }
        RepoDefinition::RepoOverride { .. } => None,
    }
}

pub fn print_streamed_jsonproto(
    definitions: &[(&str, &RepoDefinition)],
    external_directory: &str,
) -> String {
    let mut out = String::new();
    for (key, def) in definitions {
        if let Some(pb) = serialize_repo_definition_as_proto(key, def, external_directory) {
            out.push_str(&pb.to_json());
            out.push('\n');
        }
    }
    out
}

pub fn print_streamed_proto(
    definitions: &[(&str, &RepoDefinition)],
    external_directory: &str,
) -> Vec<u8> {
    let mut out = Vec::new();
    for (key, def) in definitions {
        if let Some(pb) = serialize_repo_definition_as_proto(key, def, external_directory) {
            let bytes = pb.encode_to_vec();
            encode_varint_to(&mut out, bytes.len() as u64);
            out.extend_from_slice(&bytes);
        }
    }
    out
}

fn encode_varint_to(buf: &mut Vec<u8>, mut v: u64) {
    while v >= 0x80 {
        buf.push((v as u8 & 0x7F) | 0x80);
        v >>= 7;
    }
    buf.push(v as u8);
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::AttrVal;

    #[test]
    fn prints_http_archive() {
        let spec = RepoSpec::new(
            "@bazel_tools//tools/build_defs/repo:http.bzl",
            "http_archive",
            vec![
                ("urls".into(), AttrVal::List(vec![AttrVal::Str("https://x/y.tgz".into())])),
                ("integrity".into(), AttrVal::Str("sha256-abc".into())),
                ("strip_prefix".into(), AttrVal::Str("".into())),
                ("remote_patches".into(), AttrVal::Dict(vec![])),
                ("remote_patch_strip".into(), AttrVal::Int(0)),
            ],
        );
        let def = RepoDefinition::Found { name: "bar+".into(), original_name: None, spec };
        assert_eq!(
            print_starlark("@bar_from_foo2", &def, "/ob/external"),
            "## @bar_from_foo2:\n\
             load(\"@@bazel_tools//tools/build_defs/repo:http.bzl\", \"http_archive\")\n\
             http_archive(\n  name = \"bar+\",\n  urls = [\"https://x/y.tgz\"],\n  integrity = \"sha256-abc\",\n  strip_prefix = \"\",\n  remote_patches = {},\n  remote_patch_strip = 0,\n)\n\n"
        );
    }

    #[test]
    fn prints_extension_repo_with_original_name_and_override() {
        let spec = RepoSpec::new("@@ext+//:ext.bzl", "data_repo", vec![("data".into(), AttrVal::Str("äöü€🌱".into()))]);
        let def = RepoDefinition::Found { name: "ext++ext+repo3".into(), original_name: Some("repo3".into()), spec };
        assert_eq!(
            print_starlark("@my_repo3", &def, "/e/"),
            "## @my_repo3:\nload(\"@@ext+//:ext.bzl\", \"data_repo\")\ndata_repo(\n  name = \"ext++ext+repo3\",\n  _original_name = \"repo3\",\n  data = \"äöü€🌱\",\n)\n\n"
        );
        let ov = RepoDefinition::RepoOverride { path: "/x/embedded_tools".into() };
        assert_eq!(
            print_starlark("@bazel_tools", &ov, "/e"),
            "## @bazel_tools:\nBuiltin or overridden repo located at: /x/embedded_tools\n\n"
        );
    }
}
